const d = $input.first().json;
const scope = String(d.scope || '').trim();
if (!['load_tag','activity','ingredient','other'].includes(scope)) throw new Error('недопустимый scope: ' + scope);
let value = String(d.value || '').trim();
if (!value) throw new Error('value пуст');
if (scope === 'load_tag') value = value.toLowerCase();
const st = String(d.source_type || '').trim();
const source_type = ['injury','condition','medication','client_request','research','coach'].includes(st) ? st : 'coach';
const note = String(d.note || '').trim() || null;
let sr = Number(d.source_ref);
sr = isFinite(sr) && sr > 0 ? Math.round(sr) : null;
return [{ json: { bot_id: d.bot_id, user_id: d.user_id, scope, value, source_type, note, source_ref: sr } }];
